"use client";

import { createContext, useContext, useState, type ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./avatar.css";

export type AvatarProps = Omit<ComponentProps<"span">, "children"> & {
  name: string;
  src?: string;
  alt?: string;
  /** "square" for a company, workspace or integration: a coloured mark instead of a person's orb or photo. */
  shape?: "circle" | "square";
  /** Shown as a shape at the corner: filled, half, dash or ring. */
  presence?: "online" | "away" | "busy" | "offline";
};

/** Resolves a person's photo from their name when an Avatar has no `src`: your user directory, or sample faces in a demo.
    Return undefined for anyone without one and they keep their orb. */
export const AvatarPhotos = createContext<((name: string) => string | undefined) | null>(null);

/** The same name always gets the same orb (six glass orbs; the first follows the accent). */
export function avatarTone(name: string) {
  let hash = 7;
  for (const char of name.trim().toLowerCase()) hash = (hash * 31 + char.codePointAt(0)!) >>> 0;
  return hash % 6;
}

function AvatarContent({ src, initials }: { src?: string; initials: string }) {
  const [failed, setFailed] = useState(false);
  return (
    <>
      <span aria-hidden="true">{initials}</span>
      {src && !failed && (
        <img
          src={src}
          alt=""
          aria-hidden="true"
          width={32}
          height={32}
          decoding="async"
          className="absolute inset-0 size-full object-cover"
          ref={(image) => {
            // A cached or pre-hydration failure may precede the error listener.
            if (image?.complete && image.naturalWidth === 0) setFailed(true);
          }}
          onError={() => setFailed(true)}
        />
      )}
    </>
  );
}

export function Avatar({
  name,
  src,
  alt = name,
  shape = "circle",
  presence,
  className,
  ...props
}: AvatarProps) {
  const resolve = useContext(AvatarPhotos);
  const photo = src ?? (shape === "circle" ? resolve?.(name) : undefined);
  const words = name.trim().normalize("NFC").split(/\s+/u);
  const initials =
    (Array.from(words[0] ?? "")[0] ?? "?") +
    (words.length > 1 ? (Array.from(words[words.length - 1]!)[0] ?? "") : "");

  return (
    <span
      data-slot="avatar"
      data-tone={avatarTone(name)}
      data-shape={shape === "square" ? "square" : undefined}
      className={cn(
        "relative inline-flex size-8 shrink-0 items-center justify-center text-xs font-semibold",
        shape === "square" ? "rounded-[8px]" : "rounded-full",
        className,
      )}
      {...props}
      role={alt ? "img" : undefined}
      aria-label={alt || undefined}
      aria-hidden={!alt || undefined}
    >
      <AvatarContent
        key={photo ?? ""}
        src={photo}
        initials={initials.toUpperCase()}
      />
      {presence && <span data-slot="avatar-presence" data-presence={presence} aria-hidden="true" />}
    </span>
  );
}

import { ArrowRight } from "lucide-react";
import type { ComponentProps, ElementType, ReactNode } from "react";
import { cn } from "./lib/cn";
import { StageScope } from "./stage-scope";
import "./block-concept.css";

/**
 * Marketing blocks share one voice: monochrome from the system tokens, Geist
 * display with two-tone titles, ink actions, ruled sections and ember only for
 * focus. Blocks follow the page theme, and the Caliper UI controls inside them too.
 */

export type BlockAction = { label: string; href?: string; onClick?: () => void };

/**
 * A full-bleed band. The section is the container, so everything inside lays
 * out by the block's own width; `block-inner` holds the measure and rhythm.
 * `backdrop` paints behind the content edge to edge (grid lines, a tone).
 */
export function BlockRoot({
  as: Tag = "section",
  width = "default",
  backdrop,
  tone,
  className,
  innerClassName,
  children,
  ...props
}: Omit<ComponentProps<"section">, "ref"> & {
  /** The band's element; a site footer is a footer. */
  as?: "section" | "footer" | "div";
  /** default 1240px · narrow 960px · wide 1440px. */
  width?: "default" | "narrow" | "wide";
  backdrop?: ReactNode;
  /** A band tone: the page colour or the sunken colour. */
  tone?: "page" | "sunken" | "ink";
  innerClassName?: string;
}) {
  return (
    <Tag data-slot="block" data-tone={tone} className={cn("@container relative isolate overflow-clip", className)} {...props}>
      {backdrop}
      <div data-slot="block-inner" data-width={width} className={innerClassName}>
        {children}
      </div>
    </Tag>
  );
}

export function BlockEyebrow({ className, ...props }: ComponentProps<"p">) {
  return <p data-slot="block-eyebrow" className={className} {...props} />;
}

/** A display heading in the block face. size 1 is the hero headline. */
export function BlockTitle({
  as: Tag = "h2",
  size = 2,
  className,
  ...props
}: ComponentProps<"h2"> & { as?: "h1" | "h2" | "h3"; size?: 1 | 2 | 3 }) {
  return <Tag data-slot="block-title" data-size={size} className={className} {...props} />;
}

/** The second tone of a title: these words land in grey. */
export function BlockEm({ className, ...props }: ComponentProps<"em">) {
  return <em data-slot="block-em" className={className} {...props} />;
}

export function BlockLead({ className, ...props }: ComponentProps<"p">) {
  return <p data-slot="block-lead" className={className} {...props} />;
}

/**
 * The section opening every block shares: eyebrow, title and lead. `split`
 * sets the lead beside the title on wide blocks; `center` stacks it centred.
 */
export function BlockHeader({
  eyebrow,
  title,
  lead,
  align = "start",
  aside,
  headingLevel = 2,
  className,
}: {
  eyebrow?: ReactNode;
  title: ReactNode;
  lead?: ReactNode;
  align?: "start" | "center" | "split";
  /** 1 when the block opens the page, e.g. a pricing page. */
  headingLevel?: 1 | 2;
  /** Sits at the end of the header row, e.g. a period toggle. */
  aside?: ReactNode;
  className?: string;
}) {
  return (
    <header data-slot="block-header" data-align={align} className={className}>
      <div data-slot="block-header-title">
        {eyebrow && <BlockEyebrow>{eyebrow}</BlockEyebrow>}
        <BlockTitle as={headingLevel === 1 ? "h1" : "h2"}>{title}</BlockTitle>
      </div>
      {(lead || aside) && (
        <div data-slot="block-header-aside">
          {lead && <BlockLead>{lead}</BlockLead>}
          {aside}
        </div>
      )}
    </header>
  );
}

export function BlockActions({
  primary,
  secondary,
  className,
  block = false,
}: {
  primary?: BlockAction;
  secondary?: BlockAction;
  className?: string;
  /** Full-width actions, e.g. on phones. */
  block?: boolean;
}) {
  if (!primary && !secondary) return null;
  return (
    <div data-slot="block-actions" className={cn("flex flex-wrap gap-3", block && "@max-[520px]:grid @max-[520px]:grid-cols-1", className)}>
      {primary && <BlockButton action={primary} kind="primary" arrow />}
      {secondary && <BlockButton action={secondary} kind="secondary" />}
    </div>
  );
}

export function BlockButton({ action, kind = "primary", arrow = false, link: Link = "a" }: { action: BlockAction; kind?: "primary" | "secondary"; arrow?: boolean; /** The element for a link action, e.g. your router's Link. */ link?: ElementType }) {
  const shared = { "data-slot": "block-button", "data-kind": kind } as const;
  const content = (
    <>
      {action.label}
      {arrow && <ArrowRight aria-hidden="true" data-slot="block-button-arrow" className="size-4" />}
    </>
  );
  return action.href ? (
    <Link href={action.href} {...shared}>
      {content}
    </Link>
  ) : (
    <button type="button" onClick={action.onClick} {...shared}>
      {content}
    </button>
  );
}

export function BlockCard({ className, ...props }: ComponentProps<"div">) {
  return <div data-slot="block-card" className={className} {...props} />;
}

export function BlockChip({ className, ...props }: ComponentProps<"span">) {
  return <span data-slot="block-chip" className={className} {...props} />;
}

/**
 * A product artefact on a stage: a dotted tonal panel holding a framed window, with an optional floating note that overlaps the
 * window's corner on wide blocks and sits beneath it on narrow ones.
 */
export function BlockStage({
  title,
  floating,
  bare = false,
  className,
  children,
}: {
  /** Shown in the window bar, e.g. "halden.app/close". */
  title?: string;
  floating?: ReactNode;
  /** No window frame: the children bring their own surfaces. */
  bare?: boolean;
  className?: string;
  children: ReactNode;
}) {
  return (
    <div data-slot="block-stage" className={className}>
      {bare ? (
        <StageScope>{children}</StageScope>
      ) : (
        <div data-slot="block-window">
          <div data-slot="block-window-bar" aria-hidden={title ? undefined : true}>
            <span data-slot="block-window-dots" aria-hidden="true"><i /><i /><i /></span>
            {title && <span data-slot="block-window-title">{title}</span>}
          </div>
          <div data-slot="block-window-body"><StageScope>{children}</StageScope></div>
        </div>
      )}
      {floating && <div data-slot="block-float">{floating}</div>}
    </div>
  );
}

/** Company names set as type in a quiet row; swap in SVG marks in production. */
export function BlockLogos({ label, logos, className }: { label?: string; logos: readonly string[]; className?: string }) {
  return (
    <div data-slot="block-logos" className={className}>
      {label && <p data-slot="block-logos-label">{label}</p>}
      <ul aria-label={label ?? "Customers"}>
        {logos.map((logo) => (
          <li key={logo}>{logo}</li>
        ))}
      </ul>
    </div>
  );
}

/** Initials from a name, in the block's highlight tones. */
export function BlockInitials({ name, size = 36, tone, className }: { name: string; size?: number; tone?: number; className?: string }) {
  const words = name.trim().split(/\s+/u);
  const initials = ((words[0]?.[0] ?? "") + (words.length > 1 ? (words[words.length - 1]?.[0] ?? "") : "")).toUpperCase();
  return (
    <span data-slot="block-initials" data-tone={tone === undefined ? undefined : tone % 4} aria-hidden="true" className={className} style={{ width: size, height: size, fontSize: Math.round(size / 2.8) }}>
      {initials}
    </span>
  );
}

export type BlockStat = { value: ReactNode; label: string };

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import { createContext, useContext, type ReactNode } from "react";

/**
 * True inside a block stage: a frame shown there is a demonstration on a page
 * that already has its own main landmark, so it should not add a second one.
 */
const InStage = createContext(false);

export function StageScope({ children }: { children: ReactNode }) {
  return <InStage.Provider value={true}>{children}</InStage.Provider>;
}

export const useInStage = () => useContext(InStage);

import { Avatar } from "./avatar";
import { BlockHeader, BlockRoot, BlockTitle } from "./block-concept";

export type BlockPerson = {
  name: string;
  role: string;
  /** What they are responsible for, e.g. "owns the matching engine". */
  owns: string;
  /** mailto, tel or a profile link. */
  contact?: { label: string; href: string };
};

/**
 * People introduced by what they own and how to reach them: a masthead with
 * names at display size. A photo when the name resolves one, initials when not.
 */
export function TeamBlock({
  eyebrow,
  title,
  lead,
  people,
  footnote,
  className,
}: {
  eyebrow?: string;
  title: string;
  lead?: string;
  people: readonly BlockPerson[];
  footnote?: string;
  className?: string;
}) {
  const note = footnote && <p className="mt-8 text-sm text-[var(--k-muted)]">{footnote}</p>;

  return (
    <BlockRoot className={className}>
      <BlockHeader eyebrow={eyebrow} title={title} lead={lead} align="split" />
      <ul className="border-b border-[var(--k-line)]">
        {people.map((person) => (
          <li key={person.name} className="group grid items-center gap-x-6 gap-y-1 border-t border-[var(--k-line)] py-[clamp(18px,2.4cqi,28px)] @[720px]:grid-cols-[56px_minmax(0,1.2fr)_minmax(0,1.2fr)_auto]">
            <Avatar name={person.name} alt="" className="size-12 text-sm @max-[719px]:hidden" />
            <BlockTitle as="h3" size={3} className="!text-[clamp(24px,3cqi,36px)]">{person.name}</BlockTitle>
            <span className="text-[15px] text-[var(--k-muted)]">{person.role} · {person.owns}</span>
            {person.contact && <a href={person.contact.href} className="justify-self-start font-mono text-[13px] underline-offset-4 hover:text-[var(--k-hi)] hover:underline @[720px]:justify-self-end">{person.contact.label}</a>}
          </li>
        ))}
      </ul>
      {note}
    </BlockRoot>
  );
}

/* avatar.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Avatars: a light glass orb, two soft hues with a specular highlight and a deeper lower edge. Six tones, assigned per
     person, so a row of people reads as a calm spectrum; dark initials read on every tone at 9:1 or better. */
  [data-slot="avatar"] {
    --av-a: #9ec5ff;
    --av-b: #c4b2ff;
    color: #161616;
    background:
      radial-gradient(circle at 30% 24%, rgb(255 255 255 / 80%), rgb(255 255 255 / 0%) 36%),
      radial-gradient(circle at 76% 84%, color-mix(in oklab, var(--av-b) 78%, #3b2a6b), transparent 58%),
      linear-gradient(140deg, var(--av-a) 12%, var(--av-b) 88%);
    box-shadow: inset 0 0 0 1px rgb(255 255 255 / 34%), inset 0 -4px 8px rgb(0 0 0 / 8%);
  }
  [data-slot="avatar"] > span:first-child {
    position: relative;
    text-shadow: 0 1px 0 rgb(255 255 255 / 35%);
  }
  [data-slot="avatar"] img {
    border-radius: inherit;
  }
  [data-slot="avatar"][data-tone="1"] { --av-a: #a3f0c8; --av-b: #7fd3e6; }
  [data-slot="avatar"][data-tone="2"] { --av-a: #c9adff; --av-b: #ffb2d8; }
  [data-slot="avatar"][data-tone="3"] { --av-a: #ffd6a0; --av-b: #ffab86; }
  [data-slot="avatar"][data-tone="4"] { --av-a: #ffb4a6; --av-b: #ff9ec6; }
  [data-slot="avatar"][data-tone="5"] { --av-a: #b8c6ff; --av-b: #9fe1f0; }
  /* Company marks (shape="square"): a solid hue from the name with white initials, 4.7:1 or better on every hue. */
  [data-slot="avatar"][data-shape="square"] {
    --mark-h: 255;
    color: #ffffff;
    background: oklch(0.52 0.15 var(--mark-h));
    box-shadow: inset 0 0 0 1px rgb(255 255 255 / 12%);
  }
  [data-slot="avatar"][data-shape="square"] > span:first-child { text-shadow: none; }
  [data-slot="avatar"][data-shape="square"][data-tone="1"] { --mark-h: 295; }
  [data-slot="avatar"][data-shape="square"][data-tone="2"] { --mark-h: 2; }
  [data-slot="avatar"][data-shape="square"][data-tone="3"] { --mark-h: 50; }
  [data-slot="avatar"][data-shape="square"][data-tone="4"] { --mark-h: 150; }
  [data-slot="avatar"][data-shape="square"][data-tone="5"] { --mark-h: 195; }
  [data-slot="avatar-presence"] {
    position: absolute;
    right: -3px;
    bottom: -3px;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    box-shadow: 0 0 0 2px var(--background);
  }
  [data-slot="avatar-presence"][data-presence="online"] { background: var(--success); }
  [data-slot="avatar-presence"][data-presence="away"] { background: linear-gradient(90deg, var(--warning) 50%, var(--background) 50%); box-shadow: 0 0 0 2px var(--background), inset 0 0 0 1.5px var(--warning); }
  [data-slot="avatar-presence"][data-presence="busy"] { background: radial-gradient(var(--background) 0 0) center / 5px 1.5px no-repeat, var(--danger); }
  [data-slot="avatar-presence"][data-presence="offline"] { background: var(--background); box-shadow: 0 0 0 2px var(--background), inset 0 0 0 1.5px var(--muted-foreground); }
}

/* block-concept.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* A site header used outside a block still needs the block tokens. */
  [data-slot="block"] {
    --k-display-font: var(--font-display-block, var(--font-sans, system-ui, sans-serif));
    --k-display-weight: 700;
    --k-display-case: none;
    --k-display-track: -0.03em;
    --k-display-stretch: normal;
    --k-display-lh: 1.04;
    /* Monochrome, from the system tokens, so blocks follow the page theme. */
    --k-bg: var(--background, #fff); --k-surface: var(--elevated, #fff); --k-sunken: var(--surface, #f7f7f8); --k-ink: var(--foreground, #18181b); --k-muted: var(--muted-foreground, #5d5d66); --k-line: var(--border, #e4e4e8);
    --k-line-strong: color-mix(in oklab, var(--border-strong, #8a8a94) 55%, var(--k-line));
    /* The grey second line of a two-tone title; 3:1 or better as large text in both themes. */
    --k-faint: color-mix(in oklab, var(--k-muted) 70%, var(--k-bg));
    --k-accent: var(--k-ink); --k-accent-ink: var(--k-bg); --k-hi: var(--accent-text, var(--k-ink)); --k-hi-soft: var(--accent-soft, var(--k-sunken));
    --k-focus: var(--brand, #bb4400); --k-danger: var(--danger, #c2272d);
    --k-stage: var(--surface, #f7f7f8); --k-stage-dot: color-mix(in oklab, var(--k-ink) 14%, var(--k-stage));
    --k-shadow: none;
    --k-radius: 12px; --k-radius-lg: 16px; --k-radius-xl: 20px; --k-btn-radius: 999px;
    --k-tile-1: color-mix(in oklab, var(--k-ink) 5%, var(--k-bg)); --k-tile-2: color-mix(in oklab, var(--k-ink) 8%, var(--k-bg)); --k-tile-3: color-mix(in oklab, var(--k-ink) 11%, var(--k-bg)); --k-tile-4: color-mix(in oklab, var(--k-ink) 14%, var(--k-bg));
    background: var(--k-bg);
    color: var(--k-ink);
    font-family: var(--font-sans, system-ui, sans-serif);
  }
  /* Band tones inside a concept: a sunken band, or an inverse ink band. */
  [data-slot="block"][data-tone="sunken"] { background: var(--k-sunken); }

  [data-slot="block-inner"] {
    position: relative;
    z-index: 1;
    margin-inline: auto;
    max-inline-size: 1240px;
    padding-inline: clamp(20px, 5cqi, 64px);
    padding-block: clamp(64px, 10cqi, 128px);
  }
  [data-slot="block-inner"][data-width="narrow"] { max-inline-size: 960px; }
  [data-slot="block-inner"][data-width="wide"] { max-inline-size: 1440px; }

  /* ── Type ─────────────────────────────────────────── */
  [data-slot="block-eyebrow"] {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin: 0;
    font-size: 14px;
    line-height: 20px;
    font-weight: 500;
    color: var(--k-muted);
  }

  [data-slot="block-title"] {
    margin: 0;
    font-family: var(--k-display-font);
    font-weight: var(--k-display-weight);
    font-stretch: var(--k-display-stretch);
    font-variation-settings: "wdth" var(--k-display-wdth, 100);
    text-transform: var(--k-display-case);
    letter-spacing: var(--k-display-track);
    font-optical-sizing: auto;
    text-wrap: balance;
    color: var(--k-ink);
  }
  [data-slot="block-title"][data-size="1"] { font-size: clamp(40px, 5cqi, 64px); line-height: 1.04; font-weight: 700; letter-spacing: -0.048em; }
  [data-slot="block-title"][data-size="2"] { font-size: clamp(30px, 3.4cqi, 40px); line-height: 1.1; letter-spacing: -0.04em; }
  [data-slot="block-title"][data-size="3"] { font-size: clamp(19px, 1.7cqi, 22px); line-height: 1.2; font-weight: 600; letter-spacing: -0.015em; }
  /* Two-tone titles: the emphasised words land in grey. */
  [data-slot="block-em"] { font-style: normal; color: var(--k-faint); }

  [data-slot="block-lead"] {
    margin: 0;
    max-width: 50ch;
    font-size: clamp(16px, 1.3cqi, 18px);
    line-height: 1.6;
    color: var(--k-muted);
    text-wrap: pretty;
  }

  /* The shared section opening. */
  [data-slot="block-header"] {
    display: grid;
    gap: 20px 48px;
    margin-bottom: clamp(36px, 5cqi, 64px);
  }
  [data-slot="block-header-title"] { display: grid; gap: 18px; justify-items: start; }
  [data-slot="block-header-aside"] { display: grid; gap: 16px; align-content: end; justify-items: start; }
  [data-slot="block-header"][data-align="center"] { justify-items: center; text-align: center; }
  [data-slot="block-header"][data-align="center"] :is([data-slot="block-header-title"], [data-slot="block-header-aside"]) { justify-items: center; }
  [data-slot="block-header"][data-align="center"] [data-slot="block-title"] { max-width: 18ch; }
  @container (min-width: 900px) {
    [data-slot="block-header"][data-align="split"] { grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); align-items: end; }
    [data-slot="block-header"][data-align="split"] [data-slot="block-header-aside"] { justify-items: start; padding-bottom: 6px; }
  }

  /* ── Buttons ──────────────────────────────────────── */
  [data-slot="block-button"] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    min-height: 40px;
    padding: 0 16px;
    border: 0;
    border-radius: var(--k-btn-radius);
    font: 500 14px/1 var(--font-sans, system-ui, sans-serif);
    letter-spacing: -0.005em;
    text-decoration: none;
    white-space: nowrap;
    cursor: pointer;
    transition: background-color var(--duration-fast) var(--ease-out), box-shadow var(--duration-fast) var(--ease-out), translate var(--duration-normal) var(--ease-settle);
  }
  [data-slot="block-button"][data-kind="primary"] {
    background: var(--k-accent);
    color: var(--k-accent-ink);
    box-shadow: inset 0 1px 0 rgb(255 255 255 / 14%), 0 1px 2px rgb(0 0 0 / 20%);
  }
  [data-slot="block-button"][data-kind="secondary"] {
    background: color-mix(in srgb, var(--k-surface) 60%, transparent);
    color: var(--k-ink);
    box-shadow: inset 0 0 0 1px var(--k-line-strong);
  }
  [data-slot="block-button-arrow"] { transition: translate var(--duration-normal) var(--ease-settle); }
  @media (hover: hover) {
    [data-slot="block-button"][data-kind="primary"]:hover { background: color-mix(in srgb, var(--k-accent) 86%, var(--k-bg)); }
    [data-slot="block-button"][data-kind="secondary"]:hover { background: var(--k-sunken); box-shadow: inset 0 0 0 1px var(--k-ink); }
    [data-slot="block-button"]:hover [data-slot="block-button-arrow"] { translate: 3px 0; }
  }
  [data-slot="block-button"]:active { translate: 0 var(--motion-press-travel); }
  [data-slot="block-button"]:focus-visible { outline: 2px solid var(--k-focus); outline-offset: 3px; }

  [data-slot="block-card"] {
    border-radius: var(--k-radius-lg);
    background: var(--k-surface);
    box-shadow: 0 0 0 1px var(--k-line);
  }
  [data-slot="block-chip"] {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    min-height: 28px;
    padding: 0 12px;
    border-radius: 999px;
    font-size: 13px;
    font-weight: 500;
    background: var(--k-hi-soft);
    color: var(--k-ink);
    box-shadow: inset 0 0 0 1px var(--k-line);
    text-decoration: none;
  }
  /* People in blocks are the library's light glass orbs (as Avatar), one pastel tone per person. */
  [data-slot="block-initials"] {
    --av-a: #9ec5ff;
    --av-b: #c4b2ff;
    display: inline-grid;
    flex: none;
    place-items: center;
    border-radius: 999px;
    font-weight: 600;
    color: #161616;
    background:
      radial-gradient(circle at 30% 24%, rgb(255 255 255 / 80%), rgb(255 255 255 / 0%) 36%),
      radial-gradient(circle at 76% 84%, color-mix(in oklab, var(--av-b) 78%, #3b2a6b), transparent 58%),
      linear-gradient(140deg, var(--av-a) 12%, var(--av-b) 88%);
    box-shadow: inset 0 0 0 1px rgb(255 255 255 / 34%), inset 0 -4px 8px rgb(0 0 0 / 8%);
  }
  [data-slot="block-initials"][data-tone="1"] { --av-a: #a3f0c8; --av-b: #7fd3e6; }
  [data-slot="block-initials"][data-tone="2"] { --av-a: #c9adff; --av-b: #ffb2d8; }
  [data-slot="block-initials"][data-tone="3"] { --av-a: #ffd6a0; --av-b: #ffab86; }

  /* ── Stage: a product artefact framed on a tonal panel ─ */
  [data-slot="block-stage"] {
    position: relative;
    padding: clamp(14px, 4.5cqi, 64px);
    padding-bottom: 0;
    border-radius: var(--k-radius-xl);
    background-color: var(--k-stage);
    background-image: radial-gradient(var(--k-stage-dot) 1px, transparent 1.2px);
    background-size: 16px 16px;
    box-shadow: inset 0 0 0 1px var(--k-line);
    overflow: hidden;
  }
  [data-slot="block-window"] {
    position: relative;
    overflow: hidden;
    border-radius: var(--k-radius-lg) var(--k-radius-lg) 0 0;
    background: var(--k-surface);
    box-shadow: 0 0 0 1px var(--k-line), var(--k-shadow);
  }
  [data-slot="block-window-bar"] {
    display: flex; align-items: center; gap: 12px;
    height: 40px; padding: 0 16px;
    border-bottom: 1px solid var(--k-line);
    background: color-mix(in srgb, var(--k-sunken) 55%, var(--k-surface));
  }
  [data-slot="block-window-dots"] { display: none; }
  [data-slot="block-window-dots"] i { width: 10px; height: 10px; border-radius: 999px; background: var(--k-line-strong); }
  [data-slot="block-window-title"] {
    flex: 1 1 0; min-width: 0; width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
    text-align: left;
    font-family: var(--font-mono, monospace); font-size: 12px; color: var(--k-muted);
  }
  [data-slot="block-window-body"] { padding: clamp(14px, 2.6cqi, 28px); }
  [data-slot="block-float"] {
    position: relative;
    z-index: 2;
    margin: 12px 0 14px;
  }
  @container (min-width: 760px) {
    /* Over the window bar's empty right end, so it never hides a row. */
    [data-slot="block-float"] {
      position: absolute;
      top: clamp(12px, 2.4cqi, 36px);
      right: clamp(12px, 2.4cqi, 36px);
      margin: 0;
      max-width: 320px;
    }
  }
  [data-slot="block-float"] > * {
    border-radius: var(--k-radius);
    background: var(--k-surface);
    box-shadow: 0 0 0 1px var(--k-line), var(--k-shadow);
  }

  /* ── Logos ────────────────────────────────────────── */
  [data-slot="block-logos"] { display: grid; gap: 18px; }
  [data-slot="block-logos-label"] { margin: 0; font-size: 13px; color: var(--k-muted); }
  [data-slot="block-logos"] ul { display: flex; flex-wrap: wrap; align-items: center; gap: 14px clamp(24px, 4.5cqi, 56px); margin: 0; padding: 0; list-style: none; }
  [data-slot="block-logos"] li {
    font-family: var(--k-display-font);
    font-weight: var(--k-display-weight);
    font-stretch: var(--k-display-stretch);
    text-transform: var(--k-display-case);
    font-size: clamp(18px, 2cqi, 24px);
    letter-spacing: calc(var(--k-display-track) / 2);
    color: var(--k-muted);
    white-space: nowrap;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="block-button"], [data-slot="block-button-arrow"] { transition: none; }
    [data-slot="block-button"]:active { translate: none; }
    [data-slot="block-button"]:hover [data-slot="block-button-arrow"] { translate: none; }
  }
  @media print {
    footer[data-slot="block"] { display: none !important; }
    [data-slot="block"] { background: #fff; }
  }
}
